+            ws_warning("Can't set SIGTERM signal handler");
+            return FALSE;
+    }
+    if (sigaction(SIGPIPE, &sig_handler, NULL)) {
+            ws_warning("Can't set SIGPIPE signal handler");
+            return FALSE;
+    }
+#endif /* _WIN32 */
+
+    return TRUE;
